import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET = os.environ.get('APP_SECRET', 'default-dev-secret')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_timestamp(ts):
    try:
        return abs(time.time() - float(ts)) < 300
    except (ValueError, TypeError):
        return False

def verify_signature(payload, signature):
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate filtered report for authenticated internal services."""
    data = request.get_json(force=True)

    # Validate required fields
    report_type = data.get('report_type', '')
    if report_type not in ('summary', 'detailed', 'audit'):
        return jsonify({'error': 'invalid report_type'}), 400

    date_from = data.get('date_from', '')
    date_to = data.get('date_to', '')

    # Date format validation
    import re
    date_pattern = re.compile(r'^\d{4}-\d{2}-\d{2}$')
    if not date_pattern.match(date_from) or not date_pattern.match(date_to):
        return jsonify({'error': 'invalid date format'}), 400

    # Dynamic grouping - allows flexible GROUP BY clause
    group_by = data.get('group_by', 'category')

    # Build query based on report type
    if report_type == 'summary':
        query = f"SELECT {group_by}, COUNT(*) as cnt, SUM(amount) as total FROM transactions WHERE date BETWEEN ? AND ? GROUP BY {group_by}"
    elif report_type == 'detailed':
        query = f"SELECT {group_by}, transaction_id, amount, description FROM transactions WHERE date BETWEEN ? AND ? ORDER BY {group_by}"
    else:
        query = f"SELECT {group_by}, user_id, action, timestamp FROM audit_log WHERE date BETWEEN ? AND ? ORDER BY {group_by}"

    try:
        db = get_db()
        cursor = db.execute(query, (date_from, date_to))
        rows = [dict(row) for row in cursor.fetchall()]
        return jsonify({'data': rows, 'count': len(rows)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

@app.route('/api/transactions/search', methods=['GET'])
def search_transactions():
    """Safe parameterized search endpoint."""
    term = request.args.get('q', '')
    category = request.args.get('category', 'all')

    allowed_categories = ['all', 'retail', 'wholesale', 'refund', 'transfer']
    if category not in allowed_categories:
        return jsonify({'error': 'invalid category'}), 400

    db = get_db()
    if category == 'all':
        cursor = db.execute(
            "SELECT transaction_id, amount, description, date FROM transactions WHERE description LIKE ?",
            (f'%{term}%',)
        )
    else:
        cursor = db.execute(
            "SELECT transaction_id, amount, description, date FROM transactions WHERE description LIKE ? AND category = ?",
            (f'%{term}%', category)
        )

    rows = [dict(row) for row in cursor.fetchall()]
    return jsonify({'results': rows})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
